        /**
         * UTC date as YYYYMMDD.
         */today: UInt32, 
        /**
         * 0 = do not disclose age.
         */minAge: UInt32, discloseNationality: Bool) {
        self.challenge = challenge
        self.scope = scope
        self.today = today
        self.minAge = minAge
        self.discloseNationality = discloseNationality
    }
}

